INSERT INTO public.collections (id, name, slug, description, category, tagline, cover_image, hero_image, material, finish, thickness, application, published, featured, sort_order, display_order, seo_title, seo_description)
VALUES
  (1, 'Marble Membrane Door', 'marble-membrane', 'Exquisite Italian and Spanish marble veining combined with durable vacuum membrane fusion. Features high-definition stone textures accentuated with golden radial geometry.', 'Luxury Marble Finish', 'The Majesty of Natural Stone with Timber Warmth', '/doors/door_p03_01.jpg', '/doors/door_p03_01.jpg', 'High-Density Moisture-Resistant Core + Imported Marble-Grain PVC Membrane', 'Gloss / Matte Velvet Stone Texture with Gold Accent inlays', '30mm / 32mm / 35mm', 'Living Room, Master Bed, Executive Cabin, Villa Main Internal', TRUE, FALSE, 0, 0, 'Marble Membrane Door | New Ikon Doors Trichy', 'Exquisite Italian and Spanish marble veining combined with durable vacuum membrane fusion. Features high-definition stone textures accentuated with golden '),
  (2, 'UV Membrane Door', 'uv-membrane', 'Super-glossy UV protective coating over calibrated engineered panels. Unrivaled scratch resistance and mirror-like reflection designed for modern contemporary homes.', 'Ultra-Violet High Gloss Finish', 'Dazzling Reflections That Illuminate Your Living Spaces', '/doors/door_p04_01.jpg', '/doors/door_p04_01.jpg', 'Kiln-Seasoned Hardwood Core + Multi-Layer UV Curable Resin + Membrane', 'Ultra High-Gloss UV Shield / Mirror Polish', '30mm / 32mm / 35mm / 38mm', 'Bedroom, Apartment Interior, Luxury Suite, Modern Villas', TRUE, FALSE, 1, 1, 'UV Membrane Door | New Ikon Doors Trichy', 'Super-glossy UV protective coating over calibrated engineered panels. Unrivaled scratch resistance and mirror-like reflection designed for modern contempor'),
  (3, 'Mica Door', 'mica-doors', 'Heavy-duty 1mm decorative laminates pressed with thermal waterproof adhesives. Delivers authentic timber tactile grain and resilient resistance to wear, heat, and impacts.', 'Architectural Laminate', 'Rugged Durability Meets Timeless Woodcraft', '/doors/door_p09_01.jpg', '/doors/door_p09_01.jpg', 'Solid Core Blockboard / Flush Core + 1.0mm Premium Mica Laminate', 'Natural Woodgrain Embossed / Matte Texture', '32mm / 35mm / 38mm', 'High-traffic Passages, Commercial Offices, Hospitality, Master Bedrooms', TRUE, FALSE, 2, 2, 'Mica Door | New Ikon Doors Trichy', 'Heavy-duty 1mm decorative laminates pressed with thermal waterproof adhesives. Delivers authentic timber tactile grain and resilient resistance to wear, he'),
  (4, 'Steel Patti Door', 'steel-patti', 'Architectural precision grooved stainless steel patti inlays integrated into rich walnut and charcoal wood membranes. Clean minimalist horizontal and vertical lines.', 'Metallic Inlay Architecture', 'Modern Geometric Splendor Defined by Steel', '/doors/door_p11_01.jpg', '/doors/door_p11_01.jpg', 'Moisture-Proof Engineered Composite + Brushed Stainless Steel (SS304) Inlays', 'Brushed Chrome / Titanium Metallic Inlay with Silk Wood Finish', '32mm / 35mm / 38mm', 'Contemporary Living, Main Entrances, Luxury Suites, Executive Offices', TRUE, FALSE, 3, 3, 'Steel Patti Door | New Ikon Doors Trichy', 'Architectural precision grooved stainless steel patti inlays integrated into rich walnut and charcoal wood membranes. Clean minimalist horizontal and verti'),
  (5, 'Plain Membrane Door', 'plain-membrane', 'Pure minimalist CNC routed grooves paired with warm monolithic earth tones. Clean, uncluttered, and adaptable to minimalist interior architectural aesthetics.', 'Subtle Geometric CNC Craft', 'Understated Elegance in Every Precision Groove', '/doors/door_p13_01.jpg', '/doors/door_p13_01.jpg', 'Heavy-Density Fiber Core + Seamless German Membrane Vacuum Press', 'Satin Velvet Monolith / Fine Grain Matte', '30mm / 32mm / 35mm', 'Bedrooms, Study Rooms, Hospital Suites, Commercial Developments', TRUE, FALSE, 4, 4, 'Plain Membrane Door | New Ikon Doors Trichy', 'Pure minimalist CNC routed grooves paired with warm monolithic earth tones. Clean, uncluttered, and adaptable to minimalist interior architectural aestheti'),
  (6, 'Kumil Membrane Door', 'kumil-membrane', 'Traditional South Indian artistic Kumil motifs translated into modern vacuum-sealed membrane doors. Deep carved heritage panels with lasting moisture resistance.', 'Heritage South Indian Craft', 'Sacred Traditional Motifs Reimagined for Modern Homes', '/doors/door_p17_01.jpg', '/doors/door_p17_01.jpg', 'Select Solid Core Timber + Deep CNC Carving + Heat-bonded Membrane', 'Warm Teak & Rosewood Heritage Stain Finish', '32mm / 35mm / 38mm', 'Puja Room, Traditional Entrances, Heritage Homes, Villas', TRUE, FALSE, 5, 5, 'Kumil Membrane Door | New Ikon Doors Trichy', 'Traditional South Indian artistic Kumil motifs translated into modern vacuum-sealed membrane doors. Deep carved heritage panels with lasting moisture resis'),
  (7, '3D Membrane Door', '3d-membrane', 'Multi-dimensional CNC carved relief patterns that cast subtle dynamic shadows under interior lighting. Creates dramatic sculptural presence across doorways.', 'Dimensional Sculpted Panels', 'Sculptural Depth That Transforms Flat Walls into Art', '/doors/door_p18_01.jpg', '/doors/door_p18_01.jpg', 'Calibrated Solid Core + Multi-axis 3D CNC Routing + Seamless Membrane', '3D Shadow Relief / Deep Matte Polymer', '32mm / 35mm / 40mm', 'Feature Doors, Home Theatres, Main Hall Entrances, Designer Penthouses', TRUE, FALSE, 6, 6, '3D Membrane Door | New Ikon Doors Trichy', 'Multi-dimensional CNC carved relief patterns that cast subtle dynamic shadows under interior lighting. Creates dramatic sculptural presence across doorways'),
  (8, 'Micro Coating Door', 'micro-coating', 'State-of-the-art micro-polymeric surface seal that repels smudges, dust, and water splashes while delivering a hyper-smooth velvet soft-touch experience.', 'Advanced Nano-Polymer Finish', 'The Future of Velvet Touch Micro-Engineered Finishes', '/doors/door_p19_01.jpg', '/doors/door_p19_01.jpg', 'Hydraulic Pressed Composite Core + Nano-Micro Polymeric Seal', 'Ultra-Matte Velvet Soft-Touch / Zero-Smudge Texture', '30mm / 32mm / 35mm', 'Luxury Apartments, Modern Condos, Bathrooms & Ensuites, Bedrooms', TRUE, FALSE, 7, 7, 'Micro Coating Door | New Ikon Doors Trichy', 'State-of-the-art micro-polymeric surface seal that repels smudges, dust, and water splashes while delivering a hyper-smooth velvet soft-touch experience.'),
  (9, 'WPVC Digital Door', 'wpvc-digital', 'Wood-Plastic Polymer Composite engineered for zero water absorption, zero warping, and 100% termite proofing. Features vibrant high-resolution UV digital graphics.', '100% Waterproof Composite', '100% Waterproof & Termite-Proof for Wet & Exterior Zones', '/doors/door_p23_01.jpg', '/doors/door_p23_01.jpg', '100% WPVC Solid Synthetic Polymer Composite Core', 'High-Definition Digital Print with Protective Clear Coat', '30mm / 32mm', 'Bathrooms, Restrooms, Coastal Properties, High-Moisture Utility Balconies', TRUE, FALSE, 8, 8, 'WPVC Digital Door | New Ikon Doors Trichy', 'Wood-Plastic Polymer Composite engineered for zero water absorption, zero warping, and 100% termite proofing. Features vibrant high-resolution UV digital g'),
  (10, 'Rubber Wood Door', 'rubber-wood', 'Ecologically sustainable finger-jointed treated solid rubberwood. Kiln-dried to 10% moisture content for unmatched dimensional stability and warm organic grain.', 'Sustainable Solid Hardwood', 'Natural Warmth and Strength from Sustainable Timber', '/doors/door_p24_01.jpg', '/doors/door_p24_01.jpg', '100% Solid Kiln-Dried Chemically Treated Plantation Rubberwood', 'Natural Satin Lacquer / Honey Timber Stain', '32mm / 35mm / 38mm', 'Eco-Luxury Residences, Bedrooms, Balcony Entrances, Resort Suites', TRUE, FALSE, 9, 9, 'Rubber Wood Door | New Ikon Doors Trichy', 'Ecologically sustainable finger-jointed treated solid rubberwood. Kiln-dried to 10% moisture content for unmatched dimensional stability and warm organic g')
