  ('New Ikon Doors & Ply', 'Manufacturing & Experience Showroom', 'Main Showroom & Plant', 'Direct factory showroom displaying over 130+ live architectural door elevations including UV Membrane, Marble Laminate, Steel Patti Inlays, solid Teak, and Flush Doors with custom sizing.', 'Plot No. 45 C/A1, Thanjavur Road, Near Mariyamman Kovil Bus Stop, Tharanallur, Trichy - 620008', '+91 98424 45353', '+91 98424 43353', '9842445353', 'https://www.google.com/maps/dir/?api=1&destination=New+Ikon+Doors+%26+Ply,+Thanjavur+Road,+Trichy', 'https://www.google.com/maps/dir/?api=1&destination=New+Ikon+Doors+%26+Ply,+Thanjavur+Road,+Trichy', '/doors/showroom_experience.jpg', '/doors/showroom_experience.jpg', 'Mon - Sat: 9:00 AM - 8:30 PM', 'Mon - Sat: 9:00 AM - 8:30 PM', '[]'::jsonb, TRUE, 0, 0),
  ('Classic Ply & Lam', 'Wholesale Plywoods & Core Substrates', 'Plywood & Timber Division', 'Primary wholesale stockist for commercial, marine, and boiling waterproof (BWP) grade plywoods, block boards, and seasoned hardwood door frames.', 'Thanjavur Main Road Trade Corridor, Trichy, Tamil Nadu - 620008', '+91 98424 45353', '', '9842445353', 'https://www.google.com/maps/dir/?api=1&destination=New+Ikon+Doors+%26+Ply,+Thanjavur+Road,+Trichy', 'https://www.google.com/maps/dir/?api=1&destination=New+Ikon+Doors+%26+Ply,+Thanjavur+Road,+Trichy', '/doors/classic_ply_timber_warehouse.jpg', '/doors/classic_ply_timber_warehouse.jpg', 'Mon - Sat: 9:00 AM - 8:00 PM', 'Mon - Sat: 9:00 AM - 8:00 PM', '["BWP & BWR Marine Grade Plywood","Termite & Borer Proof Hardwood Cores","Bulk Contractor & Developer Supply","Direct Mill Wholesale Sourcing"]'::jsonb, TRUE, 1, 1),
  ('Royal Lam & Ply', 'Laminates, WPVC & Edge Banding', 'Interior Solutions Division', 'Specialized distribution of designer 1mm Mica laminates, waterproof WPVC digital printed doors, high-density panels, and matching PVC edge banding.', 'Palakarai Commercial Market, Trichy, Tamil Nadu - 620001', '+91 98424 45353', '', '9842445353', 'https://www.google.com/maps/dir/?api=1&destination=New+Ikon+Doors+%26+Ply,+Thanjavur+Road,+Trichy', 'https://www.google.com/maps/dir/?api=1&destination=New+Ikon+Doors+%26+Ply,+Thanjavur+Road,+Trichy', '/doors/royal_lam_interior_showroom.jpg', '/doors/royal_lam_interior_showroom.jpg', 'Mon - Sat: 9:00 AM - 8:00 PM', 'Mon - Sat: 9:00 AM - 8:00 PM', '["High-Definition WPVC Digital Doors","Designer Laminates & 1mm Mica Sheets","Premium Matching Edge Banding Rolls","Waterproof Bathroom & Balcony Doors"]'::jsonb, TRUE, 2, 2);
INSERT INTO public.testimonials (customer_name, name, company, designation, role, location, content, quote, image_url, photo, rating, project, published, sort_order, display_order)
VALUES
  ('Ar. Karthik Sundaram', 'Ar. Karthik Sundaram', '', 'Principal Architect, Studio Vistas, Chennai & Trichy', 'Principal Architect, Studio Vistas, Chennai & Trichy', '', 'We have specified New Ikon Doors across four luxury villa projects. Their UV Membrane and Steel Patti finishes deliver the bespoke sharpness of custom carpentry with factory-grade dimensional stability.', 'We have specified New Ikon Doors across four luxury villa projects. Their UV Membrane and Steel Patti finishes deliver the bespoke sharpness of custom carpentry with factory-grade dimensional stability.', '', '', 5, 'Riverstone Residences (32 Luxury Villas)', TRUE, 0, 0),
  ('M. Rajendran', 'M. Rajendran', '', 'Managing Director, Sri Vigneshwar Builders', 'Managing Director, Sri Vigneshwar Builders', '', 'Having worked with Abbas and the New Ikon team for over 12 years, their consistency in CNC precision and zero-defect delivery across 200+ unit residential towers is second to none.', 'Having worked with Abbas and the New Ikon team for over 12 years, their consistency in CNC precision and zero-defect delivery across 200+ unit residential towers is second to none.', '', '', 5, 'Greenfield Horizon Apartment Enclave', TRUE, 1, 1),
  ('Praveen Kumar', 'Praveen Kumar', '', 'Lead Interior Designer, SpaceCraft Interiors', 'Lead Interior Designer, SpaceCraft Interiors', '', 'The Marble Membrane series astonished our clients. The seamless fusion of marble grain with warm timber feel gave the master suites an opulent luxury presence that photos barely do justice.', 'The Marble Membrane series astonished our clients. The seamless fusion of marble grain with warm timber feel gave the master suites an opulent luxury presence that photos barely do justice.', '', '', 5, 'Trichy Executive Penthouse', TRUE, 2, 2);
