VALUES
  ('In-House CNC Precision', 'Computer numerical control routing and vacuum-press membrane bonding for crisp geometric motifs and structural consistency.', 'Cpu', TRUE, TRUE, 1),
  ('Water & Moisture Resistance', 'Multi-layer protective polymer coats and WPVC compositions engineered to endure humid regional climates.', 'Droplets', TRUE, TRUE, 2),
  ('Architectural Customization', 'Custom door dimensions, distinct wood-grain tones, authentic marble veining, and metallic stainless steel inlays.', 'Layers', TRUE, TRUE, 3),
  ('Wholesale Group Synergies', 'Direct coordination with sister divisions Classic Ply & Lam and Royal Lam & Ply for consolidated trade supply.', 'ShieldCheck', TRUE, TRUE, 4);
